SELECT ?a ?b ?c ?d WHERE {
  ?ts ref:hasTimeseriesId ?id .
  ?ts a brick:ZoneTemperature ; rdfs:label ?a .
}

SELECT ?label ?cls ?id WHERE {
  ?ts ref:hasTimeseriesId ?id .
  ?ts a ?cls .
  OPTIONAL { ?ts rdfs:label ?label } .
  FILTER(str(?cls) LIKE "%Cooling%" || str(?cls) LIKE "%Zone%" || str(?cls) LIKE "%Setpoint%")
}

SELECT ?label ?cls ?id WHERE {
  ?ts ref:hasTimeseriesId ?id .
  ?ts a ?cls .
  OPTIONAL { ?ts rdfs:label ?label } .
}

SELECT ?z ?lab ?desc WHERE {
  ?z a/brick:hasSubclass* brick:Zone .
  OPTIONAL { ?z rdfs:label ?lab } .
  OPTIONAL { ?z brick:hasIdentifier ?desc } .
} LIMIT 200

